//! M4: the HLD §27 extractor registry, and XLSX / CSV / TSV / PPTX
//! extraction. Fixtures: tests/fixtures/office (generated by
//! scripts/gen-extraction-bench-fixtures.py, committed).

use aikoql_ingestion::{
    document_model_to_ast, extract_document, mime_from_extension, AstNode, AstPayload,
    DocumentExtractor, DocumentModel, DocumentSource, ExtractorRegistry, PageModel, TablePayload,
};

const DIR: &str = "tests/fixtures/office";
const XLSX: &str = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
const PPTX: &str = "application/vnd.openxmlformats-officedocument.presentationml.presentation";

fn grid(t: &TablePayload) -> Vec<Vec<String>> {
    let mut rows = vec![t.headers.iter().map(|h| h.text.clone()).collect::<Vec<_>>()];
    for r in &t.rows {
        rows.push(
            t.cells
                .iter()
                .filter(|c| c.row_id == r.id)
                .map(|c| c.text.clone())
                .collect(),
        );
    }
    rows
}

fn collect(nodes: &[AstNode], out: &mut Vec<TablePayload>) {
    for n in nodes {
        if let Some(AstPayload::Table(t)) = &n.payload {
            out.push(t.clone());
        }
        collect(&n.children, out);
    }
}

fn tables(doc: &DocumentModel, page: usize) -> Vec<Vec<Vec<String>>> {
    let ast = document_model_to_ast(doc);
    let mut out = Vec::new();
    collect(&ast.pages[page - 1].children, &mut out);
    out.iter().map(grid).collect()
}

fn rows(r: &[&[&str]]) -> Vec<Vec<String>> {
    r.iter()
        .map(|row| row.iter().map(|c| c.to_string()).collect())
        .collect()
}

#[test]
fn xlsx_each_sheet_is_a_page_with_a_table_in_workbook_order() {
    let doc = extract_document(&format!("{DIR}/workbook.xlsx"), XLSX, None).unwrap();
    assert_eq!(doc.page_count, 2);
    assert!(doc.pages[0].text.contains("Sales"), "{}", doc.pages[0].text);
    assert_eq!(
        tables(&doc, 1),
        vec![rows(&[
            &["Region", "Q1", "Q2"],
            &["North America", "1200", "1350"],
            &["Europe", "980", "1020.5"],
        ])]
    );
    // B2:B3 is merged: the merged value fills the range.
    assert_eq!(
        tables(&doc, 2),
        vec![rows(&[
            &["Name", "Team", "Location"],
            &["Alice Smith", "Billing", "Amsterdam"],
            &["Bob Johnson", "Billing", "London"],
            &["Carol White", "Ledger", "Berlin"],
        ])]
    );
}

#[test]
fn csv_sniffs_the_delimiter_and_honours_quotes() {
    let doc = extract_document(&format!("{DIR}/contacts.csv"), "text/csv", None).unwrap();
    assert_eq!(
        tables(&doc, 1),
        vec![rows(&[
            &["Name", "Company", "Note"],
            &["Smith, Alice", "Acme Corporation", "Said \"hello\" twice"],
            &["Bob Johnson", "Globex Industries", "Line one line two"],
            &["Carol White", "Initech", ""],
        ])],
        "{}",
        doc.pages[0].text
    );
    let doc = extract_document(
        &format!("{DIR}/metrics.tsv"),
        "text/tab-separated-values",
        None,
    )
    .unwrap();
    assert_eq!(
        tables(&doc, 1),
        vec![rows(&[
            &["Metric", "Value"],
            &["Uptime", "99.9%"],
            &["Latency", "120 ms"]
        ])]
    );
}

#[test]
fn pptx_slides_notes_tables_and_images() {
    let assets = std::env::temp_dir().join(format!("aikoql-pptx-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&assets);
    let doc = extract_document(
        &format!("{DIR}/deck.pptx"),
        PPTX,
        Some(&assets.to_string_lossy()),
    )
    .unwrap();
    assert_eq!(doc.page_count, 4);
    assert!(doc.pages[0].text.contains("Quarterly Review"));
    assert!(doc.pages[0].text.contains("Northwind Trading B.V."));
    assert!(doc.pages[1].text.contains("Opened an office in Berlin"));
    assert!(
        doc.pages[1].text.contains("Rotterdam warehouse"),
        "speaker notes kept: {}",
        doc.pages[1].text
    );
    assert_eq!(
        tables(&doc, 3),
        vec![rows(&[
            &["Region", "Q1", "Q2"],
            &["North America", "1,200", "1,350"],
            &["Europe", "980", "1,020"],
        ])]
    );
    assert_eq!(doc.pages[3].images.len(), 1, "slide picture is an asset");
    let hash = &doc.pages[3].images[0].asset.content_hash;
    assert!(assets.join(format!("{hash}.bin")).exists());
    let _ = std::fs::remove_dir_all(&assets);
}

#[test]
fn registry_selects_by_mime_and_accepts_custom_extractors() {
    let reg = ExtractorRegistry::with_defaults();
    for (mime, name) in [
        ("application/pdf", "pdf"),
        (
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "docx",
        ),
        (XLSX, "xlsx"),
        (PPTX, "pptx"),
        ("text/csv", "csv"),
        ("text/tab-separated-values", "csv"),
        ("text/html", "html"),
        ("text/plain", "text"),
        ("text/markdown", "text"),
        ("image/png", "image"),
    ] {
        assert_eq!(
            reg.extractor_for(mime).map(|e| e.name().to_string()),
            Some(name.to_string()),
            "{mime}"
        );
    }
    assert!(reg.extractor_for("application/zip").is_none());
    let err = extract_document("/nonexistent", "application/zip", None).unwrap_err();
    assert!(err.contains("unsupported mime type"), "{err}");

    struct Upper;
    impl DocumentExtractor for Upper {
        fn name(&self) -> &str {
            "upper"
        }
        fn supports(&self, mime_type: &str) -> bool {
            mime_type == "application/x-upper"
        }
        fn extract(&self, source: &DocumentSource) -> Result<DocumentModel, String> {
            let text = source.path.to_uppercase();
            Ok(DocumentModel {
                page_count: 1,
                total_chars: text.len(),
                pages: vec![PageModel {
                    page_number: 1,
                    char_count: text.len(),
                    text,
                    source: "native".into(),
                    ocr_confidence: None,
                    images: vec![],
                }],
                ocr_stats: None,
            })
        }
    }
    let mut reg = ExtractorRegistry::with_defaults();
    reg.register(Box::new(Upper));
    let doc = reg
        .extract(&DocumentSource {
            path: "abc",
            mime_type: "application/x-upper",
            asset_dir: None,
            policy: &aikoql_ingestion::ProcessingPolicy::default(),
        })
        .unwrap();
    assert_eq!(doc.pages[0].text, "ABC");
}

#[test]
fn extensions_map_to_the_extractable_mime_types() {
    for (file, mime) in [
        ("a.pdf", "application/pdf"),
        (
            "a.DOCX",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ),
        ("a.xlsx", XLSX),
        ("a.pptx", PPTX),
        ("a.csv", "text/csv"),
        ("a.tsv", "text/tab-separated-values"),
        ("a.html", "text/html"),
        ("a.htm", "text/html"),
        ("a.md", "text/markdown"),
        ("a.txt", "text/plain"),
        ("a.png", "image/png"),
    ] {
        assert_eq!(mime_from_extension(file), mime, "{file}");
    }
}
